import { Route, Routes } from 'react-router-dom'
import Home from './pages/Home'
import Prato from './pages/Prato/1' // Página que exibe o modal

type RotasProps = {
  openModal: () => void
  closeModal: () => void
}

const Rotas = ({ openModal, closeModal }: RotasProps) => {
  return (
    <Routes>
      <Route path="/" element={<Home />} />
      <Route
        path="/prato/:pratoId"
        element={<Prato openModal={openModal} closeModal={closeModal} />}
      />
    </Routes>
  )
}

export default Rotas
